import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CegG7-6m.js";var i=JSON.parse(`{"title":"Stalled Jobs","description":"","frontmatter":{},"headers":[],"relativePath":"guide/workers/stalled-jobs.md","filePath":"guide/workers/stalled-jobs.md","lastUpdated":1700347417000}`),a={name:`guide/workers/stalled-jobs.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="stalled-jobs" tabindex="-1">Stalled Jobs <a class="header-anchor" href="#stalled-jobs" aria-label="Permalink to “Stalled Jobs”">​</a></h1><p>Due to the nature of NodeJS, which is (in general) single threaded and consists of an event loop to handle the asynchronous operations, the process function needs to be written carefully so that the CPU is not occupied for a long time.</p><p>When a job reaches a worker and starts to be processed, BullMQ will place a lock on this job to protect the job from being modified by any other client or worker. At the same time, the worker needs to periodically notify BullMQ that it is still working on the job.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>This period is configured with the <code>stalledInterval</code> setting, which normally you should not need to modify.</p></div><p>However if the CPU is very busy (due to the process being very CPU intensive), the worker may not have time to renew the lock and tell the queue that it is still working on the job, which is likely to result in the job being marked as <em>stalled</em>.</p><p>A stalled job is moved back to the waiting status and will be processed again by another worker, or if it has reached its maximum number of stalls, it will be moved to the <em>failed</em> set.</p><p>Therefore, it is very important to make sure the workers return control to the NodeJS event loop often enough to avoid this kind of problem.</p>`,7)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};